import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts a bare list_sessions frame, with or without limit and before, and drops every other field', () => {
    const bare = validateMessage({type: 'list_sessions'});
    const paged = validateMessage({
      type: 'list_sessions',
      limit: 7,
      before: {updatedAt: '2026-03-03T00:00:00.000Z', sessionId: 'cursor-1'},
      userId: 'stranger',
    });
    const epoch = validateMessage({type: 'list_sessions', before: {updatedAt: 1772150400000, sessionId: 'cursor-1'}});
    const zero = validateMessage({type: 'list_sessions', limit: 0});

    expect({bare, paged, epoch, zero}).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      paged: {
        valid: true,
        data: {type: 'list_sessions', limit: 7, before: {updatedAt: '2026-03-03T00:00:00.000Z', sessionId: 'cursor-1'}},
      },
      epoch: {valid: true, data: {type: 'list_sessions', before: {updatedAt: 1772150400000, sessionId: 'cursor-1'}}},
      zero: {valid: true, data: {type: 'list_sessions', limit: 0}},
    });
  });

  it('rejects a limit or before that is not the frame the spec describes, naming the field', () => {
    const limits = ['many', -5, 2.5, null].map(limit => validateMessage({type: 'list_sessions', limit}));
    const cursors = [
      '2026-03-03T00:00:00.000Z',
      {updatedAt: '2026-03-03T00:00:00.000Z'},
      {updatedAt: '2026-03-03T00:00:00.000Z', sessionId: 'x'.repeat(150)},
      {updatedAt: 'the day before yesterday', sessionId: 'cursor-2'},
      {updatedAt: true, sessionId: 'cursor-2'},
    ].map(before => validateMessage({type: 'list_sessions', before}));

    expect({limits, cursors}).toEqual({
      limits: Array(4).fill({
        valid: false,
        error: 'list_sessions limit, when given, must be a non-negative integer',
      }),
      cursors: [
        {valid: false, error: 'list_sessions before, when given, must be an object'},
        {valid: false, error: 'list_sessions before sessionId must be a string of 1 to 128 characters'},
        {valid: false, error: 'list_sessions before sessionId must be a string of 1 to 128 characters'},
        {valid: false, error: 'list_sessions before updatedAt must be a date Date.parse accepts'},
        {valid: false, error: 'list_sessions before updatedAt must be a timestamp string or a number'},
      ],
    });
  });
});

